/** Small read-only client for Atlassian's own hosted API. Not a dashboard server or proxy. */
final class JiraMcp {
 static final String RESOURCE="https://mcp.atlassian.com/v2/mcp",CLOUD="fec5858e-2f31-4fc4-b44a-1a837d389a96";
 static final Set<String> TOOLS=Set.of("getAccessibleAtlassianResources","atlassianUserInfo","searchJiraIssuesUsingJql");
 interface Reader{Object call(String name,JSONObject arguments)throws Exception;}
 private final String token;private String session="",protocol="2025-06-18";private long sequence;
 JiraMcp(String token)throws Exception{if(token==null||token.isBlank()||token.contains("\r")||token.contains("\n"))throw new IllegalArgumentException("Missing Jira authorization");this.token=token;JSONObject result=rpc("initialize",new JSONObject().put("protocolVersion",protocol).put("capabilities",new JSONObject()).put("clientInfo",new JSONObject().put("name","Middle-earth Command").put("version","0.6")),true);String version=result.getString("protocolVersion");if(!Set.of("2024-11-05","2025-03-26","2025-06-18","2026-07-28").contains(version))throw new IllegalStateException("Jira returned an unsupported protocol version.");protocol=version;rpc("notifications/initialized",new JSONObject(),false);}
 Object call(String name,JSONObject arguments)throws Exception{if(!TOOLS.contains(name))throw new IllegalArgumentException("Only fixed Jira reads are supported");return unpack(rpc("tools/call",new JSONObject().put("name",name).put("arguments",arguments),true));}
 private JSONObject rpc(String method,JSONObject params,boolean responseRequired)throws Exception{
  long id=++sequence;JSONObject request=new JSONObject().put("jsonrpc","2.0").put("method",method).put("params",params);if(responseRequired)request.put("id",id);byte[] body=request.toString().getBytes(StandardCharsets.UTF_8);HttpURLConnection c=(HttpURLConnection)new URL(RESOURCE).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Accept","application/json, text/event-stream");c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("MCP-Protocol-Version",protocol);if(!session.isEmpty())c.setRequestProperty("Mcp-Session-Id",session);c.setFixedLengthStreamingMode(body.length);
  try{try(OutputStream out=c.getOutputStream()){out.write(body);}int status=c.getResponseCode();if(status==429)throw new BoundedHttp.RateLimitException(BoundedHttp.retryAfter(c.getHeaderField("Retry-After")));if(status==401||status==403)throw new IllegalStateException("Reconnect Jira in Accounts to review its permissions.");if(status<200||status>=300)throw new IllegalStateException("Jira could not be read. Saved information is unchanged.");String handle=c.getHeaderField("Mcp-Session-Id");if(handle!=null){if(handle.length()>512||handle.contains("\r")||handle.contains("\n"))throw new IllegalStateException("Invalid Jira session response.");session=handle;}if(!responseRequired)return new JSONObject();try(InputStream in=new LimitedInput(c.getInputStream())){JSONObject response;if(String.valueOf(c.getContentType()).contains("text/event-stream")){BufferedReader reader=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));String line;StringBuilder event=new StringBuilder();int size=0;response=null;while((line=reader.readLine())!=null){size+=line.getBytes(StandardCharsets.UTF_8).length+1;if(size>262144)throw new IllegalStateException("Jira response is too large.");if(line.startsWith("data:")){if(event.length()>0)event.append('\n');event.append(line.substring(5).trim());}else if(line.isEmpty()&&event.length()>0){JSONObject item=new JSONObject(event.toString());event.setLength(0);if(item.has("id")&&item.optLong("id",-1)==id){response=item;break;}}}if(response==null)throw new IllegalStateException("Jira did not return a result.");}else{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>262144)throw new IllegalStateException("Jira response is too large.");out.write(buffer,0,n);}response=new JSONObject(out.toString(StandardCharsets.UTF_8.name()));}if(response.optLong("id",-1)!=id||response.has("error"))throw new IllegalStateException("Jira could not complete this read.");return response.getJSONObject("result");}}finally{c.disconnect();}
 }
 private static final class LimitedInput extends FilterInputStream {private int count;LimitedInput(InputStream in){super(in);}private void add(int n)throws IOException{if(n>0&&(count+=n)>262144)throw new IOException("Jira response exceeded its limit");}@Override public int read()throws IOException{int value=in.read();if(value>=0)add(1);return value;}@Override public int read(byte[] bytes,int offset,int length)throws IOException{int n=in.read(bytes,offset,Math.min(length,262145-count));add(n);return n;}}
 static Object unpack(JSONObject result)throws Exception{if(result.optBoolean("isError"))throw new IllegalStateException("Jira did not allow this read. Review the connection in Accounts.");Object data=result.opt("structuredContent");if(data==null||data==JSONObject.NULL){JSONArray content=result.optJSONArray("content");if(content==null||content.length()!=1||!content.getJSONObject(0).optString("type").equals("text"))throw new IllegalStateException("Jira returned an unfamiliar response.");data=new JSONTokener(content.getJSONObject(0).getString("text")).nextValue();}if(data instanceof JSONObject object&&object.has("data"))data=object.get("data");if(!(data instanceof JSONObject||data instanceof JSONArray))throw new IllegalStateException("Jira returned an unfamiliar response.");return data;}
 static void verify(Reader reader)throws Exception{
  Object raw=reader.call("getAccessibleAtlassianResources",new JSONObject());JSONArray resources=raw instanceof JSONArray?(JSONArray)raw:((JSONObject)raw).optJSONArray("resources");boolean allowed=false;if(resources!=null)for(int n=0;n<Math.min(resources.length(),50);n++){JSONObject resource=resources.getJSONObject(n);if(CLOUD.equals(resource.optString("id"))&&Set.of("https://76fireworks.atlassian.net","https://76fireworks.atlassian.net/").contains(resource.optString("url")))allowed=true;}if(!allowed)throw new IllegalStateException("Choose the 76 Fireworks Jira site.");Object identity=reader.call("atlassianUserInfo",new JSONObject());if(!(identity instanceof JSONObject user)||!GoogleConnection.expected("work").equalsIgnoreCase(user.optString("email",user.optString("emailAddress"))))throw new IllegalStateException("Choose your dickersona@76fireworks.com Jira account.");
 }
 static List<FeedStore.Row> read(Reader reader)throws Exception{
  JSONObject args=new JSONObject().put("cloudId",CLOUD).put("jql","assignee = currentUser() AND statusCategory != Done ORDER BY priority DESC, updated DESC").put("maxResults",20).put("fields",new JSONArray(List.of("summary","status","priority"))).put("view","compact").put("searchResultMode","issues");Object value=reader.call("searchJiraIssuesUsingJql",args);if(!(value instanceof JSONObject data))throw new IllegalStateException("Jira returned an unfamiliar response.");Object found=data.opt("issues");JSONArray issues=found instanceof JSONArray?(JSONArray)found:found instanceof JSONObject?((JSONObject)found).optJSONArray("nodes"):null;if(issues==null)throw new IllegalStateException("Jira returned an unfamiliar issue list.");List<FeedStore.Row> rows=new ArrayList<>();for(int n=0;n<Math.min(20,issues.length());n++){JSONObject issue=issues.getJSONObject(n),fields=issue.getJSONObject("fields");String key=issue.optString("key");if(!key.matches("[A-Z][A-Z0-9_]*-\\d+"))throw new IllegalStateException("Jira returned an unfamiliar issue identifier.");JSONObject state=fields.optJSONObject("status"),priority=fields.optJSONObject("priority");rows.add(new FeedStore.Row(fields.optString("summary",key),key+" · "+(state==null?"Unknown status":state.optString("name"))+" · "+(priority==null?"Unspecified priority":priority.optString("name")),R.drawable.brand_jira));}return rows;
 }
}
